sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.searchText = '';

    c.checkAvailability = function(hallId, startDate, endDate) {
        if (!startDate || !endDate) {
            angular.forEach($scope.data.halls, function(hall) {
                if (hall.sys_id == hallId) {
                    hall.availabilityMessage = 'Please select both start and end dates.';
                }
            });
            $scope.$apply();
            return;
        }

        c.server.get({
            action: 'checkAvailability',
            hallId: hallId,
            startDate: startDate,
            endDate: endDate
        }).then(function(response) {
            angular.forEach($scope.data.halls, function(hall) {
                if (hall.sys_id == hallId) {
                    hall.availabilityMessage = response.data.availability == 'available' ?
                    'Hall is available!' :
                    'Sorry, this hall is already booked for the selected time.';
                }
            });
            $scope.$apply();
        });
    };

c.bookHall = function(hallId, startDate, endDate) {
    // Redirect to booking page with hall and dates in URL
    var url = '?id=sports_booking' + 
              '&hallId=' + hallId;

    if (startDate) {
        url += '&startDate=' + encodeURIComponent(startDate);
    }
    if (endDate) {
        url += '&endDate=' + encodeURIComponent(endDate);
    }

    window.location.href = url;
};
};

sp_widget.css:
.sports-hall-list {
  padding: 10px;

  h3 {
    color: #00695C;
    font-weight: bold;
    margin-bottom: 15px;
    padding-bottom: 10px;
    border-bottom: 2px solid #00695C;
  }

  .filter-section input {
    border-radius: 20px;
    border: 1px solid #00695C;
    padding: 8px 15px;

    &:focus {
      outline: none;
      box-shadow: 0 0 5px rgba(0,105,92,0.3);
    }
  }

  .hall-card {
    border: none !important;
    border-radius: 12px !important;
    padding: 18px !important;
    margin-bottom: 15px !important;
    background: white !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08) !important;
    transition: box-shadow 0.2s ease;

    &:hover {
      box-shadow: 0 4px 16px rgba(0,0,0,0.15) !important;
    }

    h4 {
      font-weight: bold;
      font-size: 16px;
    }

    .btn-primary {
      background: #00695C;
      border: none;
      border-radius: 20px;
      padding: 6px 20px;

      &:hover {
        background: #004D40;
      }
    }

    .btn-info {
      border-radius: 20px;
      padding: 4px 15px;
      font-size: 12px;
    }

    .btn-default {
      border-radius: 20px;
      padding: 6px 20px;
    }
  }
}

sp_widget.script:
(function() {
    // Handle availability check
    if (input && input.action == 'checkAvailability') {
    var hallId = input.hallId;
    var startDate = input.startDate;
    var endDate = input.endDate;

    gs.info('Checking: hall=' + hallId + ' start=' + startDate + ' end=' + endDate, 'AvailabilityCheck');

    var gr = new GlideRecord('x_1954179_sports_0_sports_hall_booking');
    gr.addQuery('sports_hall', hallId);
    gr.addQuery('status', 'Approved');
    gr.query();

    var isBooked = false;
    while (gr.next()) {
        var existingStart = gr.getValue('start_date');
        var existingEnd = gr.getValue('end_date');
        gs.info('Existing: ' + existingStart + ' to ' + existingEnd, 'AvailabilityCheck');
        if (startDate < existingEnd && endDate > existingStart) {
            isBooked = true;
            break;
        }
    }

    data.availability = isBooked ? 'unavailable' : 'available';
    gs.info('Result: ' + data.availability, 'AvailabilityCheck');
    return;
}

    // Load halls
    var grbook = new GlideRecord('x_1954179_sports_0_sports_hall');
    grbook.addActiveQuery();
    grbook.orderBy('hall_name');
    grbook.query();

    data.halls = [];
    while (grbook.next()) {
        var hall = {
            sys_id: grbook.getUniqueValue(),
            name: grbook.getValue('hall_name'),
            location: grbook.getValue('location'),
            capacity: grbook.getValue('capacity'),
            facilities: grbook.getValue('facilities'),
            available: true
        };

        var booking = new GlideRecord('x_1954179_sports_0_sports_hall_booking');
        booking.addQuery('sports_hall', grbook.getUniqueValue());
        booking.addQuery('status', 'Approved');
        var now = new GlideDateTime();
        booking.addQuery('start_date', '<=', now);
        booking.addQuery('end_date', '>=', now);
        booking.query();

        if (booking.next()) {
            hall.available = false;
        }

        data.halls.push(hall);
    }
})();
